#!/usr/bin/env bash
# Regenerates the IP lists in lists/ from their upstream sources. Run from
# anywhere; the update-lists workflow runs it weekly.
#
# To add a service, fetch its source once and call write_list for each list.
set -euo pipefail

cd "$(dirname "$0")/../.."
out=lists

fetch() {
	local auth=()
	# Unauthenticated GitHub API requests share a small rate limit per IP,
	# which hosted runners often exhaust.
	if [[ -n ${GITHUB_TOKEN:-} && $1 == https://api.github.com/* ]]; then
		auth=(-H "Authorization: Bearer $GITHUB_TOKEN")
	fi
	curl -fsSL --retry 3 "${auth[@]}" "$1"
}

# write_list <name> <description> <source url> reads one CIDR per line from
# stdin and writes lists/<name>.txt. It refuses an empty result, so a broken
# source fails the run instead of publishing an empty list.
write_list() {
	local name=$1 desc=$2 src=$3 file="$out/$1.txt" body
	body=$(grep -v '^[[:space:]]*$' | LC_ALL=C sort -u || true)
	if [[ -z $body ]]; then
		echo "$name: no entries from $src" >&2
		return 1
	fi
	mkdir -p "$(dirname "$file")"
	{
		echo "# $desc"
		echo "# Source: $src"
		echo "# Generated by .github/scripts/update-lists.sh; do not edit."
		echo "$body"
	} >"$file.tmp"
	mv "$file.tmp" "$file"
	echo "$name: $(wc -l <<<"$body") entries"
}

github() {
	local src=https://api.github.com/meta meta
	meta=$(fetch "$src")
	jq -er '.hooks[]' <<<"$meta" | write_list github/hooks "GitHub webhook source addresses (hooks)" "$src"
	jq -er '.actions[]' <<<"$meta" | write_list github/actions "GitHub-hosted Actions runners (actions)" "$src"
}

github
